SELECT a.point_code AS point_code, COALESCE(q.item_code, '') AS item_code, COUNT(*) AS wrong FROM progress_answer a LEFT JOIN quiz_question q ON q.question_no = a.question_no AND q.subject_id = a.subject_id WHERE a.subject_id = CAST(:subject AS INTEGER) AND substr(a.at, 1, 10) >= :since AND a.correct = 0 AND instr(:names, '|' || a.learner || '|') > 0 GROUP BY a.point_code, COALESCE(q.item_code, '') ORDER BY a.point_code ASC, wrong DESC, item_code ASC
